import emcee, numpy as np
def log_prob(x):
    return -0.5 * np.sum(x**2)
sampler = emcee.EnsembleSampler(8, 2, log_prob)
state = sampler.run_mcmc(np.random.randn(8, 2), 100)
print("rata-rata sampel:", sampler.get_chain(flat=True).mean(axis=0))

